<script setup lang="ts">
import {computed,ref} from 'vue'
import {useDb} from '../../../stores/db'
import {StatusBadge,FilePicker} from '../../../components/shared'
import {fmtMoney} from '../../../lib/money'
import {monthlyMortgage} from '../../../lib/mortgage'
const db=useDb(),proof=ref<File|null>(null),message=ref(''),principal=ref(450000),rate=ref(4.2),years=ref(30)
const bill=computed(()=>db.data.bills.find(item=>item.caseId==='case-demo')!),allocated=computed(()=>db.data.allocations.filter(a=>a.billId===bill.value.id&&a.verified).reduce((sum,a)=>sum+a.amountMinor,0)),outstanding=computed(()=>bill.value.amountMinor-allocated.value),monthly=computed(()=>monthlyMortgage(principal.value*100,rate.value,years.value*12))
function upload(){message.value=proof.value?'Pending evidence saved. It does not reduce the outstanding bill.':''}
</script>
<template><div class="page"><header class="page-header"><div><p class="eyebrow">Purchase money</p><h1>Payments</h1><p>Only verified, matched allocations reduce the outstanding purchase bill.</p></div></header><p v-if="message" class="card">{{message}}</p><section class="card"><h2>{{bill.label}}</h2><div class="data-list"><p class="data-row"><span>Bill</span><strong>{{fmtMoney(bill.amountMinor)}}</strong></p><p class="data-row"><span>Verified bank allocation</span><strong>{{fmtMoney(4000000)}}</strong></p><p class="data-row"><span>Verified purchaser allocation</span><strong>{{fmtMoney(500000)}}</strong></p><p class="data-row"><span>Outstanding</span><strong>{{fmtMoney(outstanding)}}</strong></p></div><p class="source-meta">Mortgage schedule is separate. Purchaser access creates no purchaser fee.</p></section><section class="card"><h2>Upload payment evidence</h2><FilePicker @selected="proof=$event"/><el-button type="primary" :disabled="!proof" @click="upload">Upload screenshot</el-button></section><section class="card form-grid"><h2 class="wide">Mortgage estimate</h2><label>Loan amount (RM)<input v-model.number="principal" type="number"></label><label>Annual rate %<input v-model.number="rate" type="number" step="0.1"></label><label>Years<input v-model.number="years" type="number"></label><article class="wide"><span class="source-meta">Estimated monthly repayment</span><strong class="kpi-value">{{monthly===null?'N/A':fmtMoney(monthly)}}</strong><p>Estimate only. It grants no loan approval.</p></article></section></div></template>
